Here is the commit message:
net: stmmac: Clear receive all(RA) bit when promiscuous mode
 is off

In promiscuous mode Receive All bit is set in GMAC packet filter register,
but outside promiscuous mode Receive All bit is not cleared,
which resulted in all network packets are received when toggle (ON/OFF)
the promiscuous mode.

Fixes: e0f9956a3862 ("net: stmmac: Add option for VLAN filter fail queue enable")
Signed-off-by: Ramesh Babu B <ramesh.babu.b@intel.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug occurs because the Receive All (RA) bit in the GMAC packet filter register is not cleared when promiscuous mode is turned off. This results in the device continuing to receive all network packets even when it should only receive packets that are specifically addressed to it or broadcast packets, leading to unintended packet capture behavior.

Here is the patch:

 static void dwmac4_set_filter(struct mac_device_info *hw,
 			      struct net_device *dev)
 {
 	void __iomem *ioaddr = (void __iomem *)dev->base_addr;
 	int numhashregs = (hw->multicast_filter_bins >> 5);
 	int mcbitslog2 = hw->mcast_bits_log2;
 	unsigned int value;
 	u32 mc_filter[8];
 	int i;

 	memset(mc_filter, 0, sizeof(mc_filter));

 	value = readl(ioaddr + GMAC_PACKET_FILTER);
 	value &= ~GMAC_PACKET_FILTER_HMC;
 	value &= ~GMAC_PACKET_FILTER_HPF;
 	value &= ~GMAC_PACKET_FILTER_PCF;
 	value &= ~GMAC_PACKET_FILTER_PM;
 	value &= ~GMAC_PACKET_FILTER_PR;
+	value &= ~GMAC_PACKET_FILTER_RA;
 	if (dev->flags & IFF_PROMISC) {
 		/* VLAN Tag Filter Fail Packets Queuing */
 		if (hw->vlan_fail_q_en) {
 			value = readl(ioaddr + GMAC_RXQ_CTRL4);
 			value &= ~GMAC_RXQCTRL_VFFQ_MASK;
 			value |= GMAC_RXQCTRL_VFFQE |
 				 (hw->vlan_fail_q << GMAC_RXQCTRL_VFFQ_SHIFT);
 			writel(value, ioaddr + GMAC_RXQ_CTRL4);
 			value = GMAC_PACKET_FILTER_PR | GMAC_PACKET_FILTER_RA;
 		} else {
 			value = GMAC_PACKET_FILTER_PR | GMAC_PACKET_FILTER_PCF;
 		}

 	} else if ((dev->flags & IFF_ALLMULTI) ||
 		   (netdev_mc_count(dev) > hw->multicast_filter_bins)) {
 		/* Pass all multi */
 		value |= GMAC_PACKET_FILTER_PM;
 		/* Set all the bits of the HASH tab */
 		memset(mc_filter, 0xff, sizeof(mc_filter));
 	} else if (!netdev_mc_empty(dev) && (dev->flags & IFF_MULTICAST)) {
 		struct netdev_hw_addr *ha;

 		/* Hash filter for multicast */
 		value |= GMAC_PACKET_FILTER_HMC;

 		netdev_for_each_mc_addr(ha, dev) {
 			/* The upper n bits of the calculated CRC are used to
 			 * index the contents of the hash table. The number of
 			 * bits used depends on the hardware configuration
 			 * selected at core configuration time.
 			 */
 			u32 bit_nr = bitrev32(~crc32_le(~0, ha->addr,
 					ETH_ALEN)) >> (32 - mcbitslog2);
 			/* The most significant bit determines the register to
 			 * use (H/L) while the other 5 bits determine the bit
 			 * within the register.
 			 */
 			mc_filter[bit_nr >> 5] |= (1 << (bit_nr & 0x1f));
 		}
 	}

 	for (i = 0; i < numhashregs; i++)
 		writel(mc_filter[i], ioaddr + GMAC_HASH_TAB(i));

 	value |= GMAC_PACKET_FILTER_HPF;

 	/* Handle multiple unicast addresses */
 	if (netdev_uc_count(dev) > hw->unicast_filter_entries) {
 		/* Switch to promiscuous mode if more than 128 addrs
 		 * are required
 		 */
 		value |= GMAC_PACKET_FILTER_PR;
 	} else {
 		struct netdev_hw_addr *ha;
 		int reg = 1;

 		netdev_for_each_uc_addr(ha, dev) {
 			dwmac4_set_umac_addr(hw, ha->addr, reg);
 			reg++;
 		}

 		while (reg < GMAC_MAX_PERFECT_ADDRESSES) {
 			writel(0, ioaddr + GMAC_ADDR_HIGH(reg));
 			writel(0, ioaddr + GMAC_ADDR_LOW(reg));
 			reg++;
 		}
 	}

 	/* VLAN filtering */
 	if (dev->features & NETIF_F_HW_VLAN_CTAG_FILTER)
 		value |= GMAC_PACKET_FILTER_VTFE;

 	writel(value, ioaddr + GMAC_PACKET_FILTER);

 	if (dev->flags & IFF_PROMISC && !hw->vlan_fail_q_en) {
 		if (!hw->promisc) {
 			hw->promisc = 1;
 			dwmac4_vlan_promisc_enable(dev, hw);
 		}
 	} else {
 		if (hw->promisc) {
 			hw->promisc = 0;
 			dwmac4_restore_hw_vlan_rx_fltr(dev, hw);
 		}
 	}
 }



